public void handleInputEvent(InputEvent event) {
    Optional<KeyMapping> keyOpt = getPressedKeyBinding();
    keyOpt.ifPresent(key -> {
        LocalPlayer player = Minecraft.getInstance().player;
        if (key == LEAP && Minecraft.getInstance().options.keyJump.isDown()) {
            if (Helper.isWerewolf(player)) {
                WerewolfPlayer werewolf = WerewolfPlayer.get(player);
                if (!werewolf.getActionHandler().isActionOnCooldown(ModActions.LEAP.get()) && werewolf.getForm().isTransformed()) {
                    player.connection.send(new ServerboundSimpleInputEventPacket(ServerboundSimpleInputEventPacket.Action.LEAP));
                    werewolf.getActionHandler().toggleAction(ModActions.LEAP.get(), new ActionHandler.ActivationContext());
                }
            }
        } else if (key == BITE) {
            if (Helper.isWerewolf(player)) {
                WerewolfPlayer werewolf = WerewolfPlayer.get(player);
                HitResult mouseOver = Minecraft.getInstance().hitResult;
                Entity entity = mouseOver instanceof EntityHitResult ? ((EntityHitResult) mouseOver).getEntity() : null;
                if (entity instanceof LivingEntity && werewolf.canBite() && werewolf.canBiteEntity(((LivingEntity) entity))) {
                    player.connection.send(new ServerboundBiteEventPackage(((EntityHitResult) mouseOver).getEntity().getId()));
                    clientEventHandler.onZoomPressed();
                }
            }
        }
    });
}

public void onZoomPressed() {
    this.zoomTime = 20;
    this.zoomAmount = Minecraft.getInstance().options.fov().get() / 4f / this.zoomTime;
    this.zoomModifier = Minecraft.getInstance().options.fov().get() - Minecraft.getInstance().options.fov().get() / 4f;
}

public void onFOVModifier(ViewportEvent.ComputeFov event) {
    if (this.zoomTime > 0) {
        event.setFOV(event.getFOV() - this.zoomModifier);
        this.zoomModifier -= this.zoomAmount;
        --this.zoomTime;
    }
}

protected boolean activate(IWerewolfPlayer iWerewolfPlayer, ActivationContext context) {
    WerewolfPlayer player = ((WerewolfPlayer) iWerewolfPlayer);
    List<Mob> entities = player.getRepresentingPlayer().level().getEntitiesOfClass(Mob.class, new AABB(player.getRepresentingEntity().blockPosition()).inflate(10, 3, 10), (entity -> !(Helper.isWerewolf(entity))));
    for (Mob entity : entities) {
        entity.setTarget(null);
        entity.getNavigation().stop();
        Path path = entity.getNavigation().createPath(entity.blockPosition().offset(Helper.multiplyBlockPos(entity.blockPosition().subtract(player.getRepresentingEntity().blockPosition()), 3)), 0);
        entity.getNavigation().moveTo(path, 1.7);
    }
    return true;
}

